    root: &Path,
    agent: &Agent,
    skew: i64,
) -> Result<Result<String, String>, E> {
    if skew < 0 { return Err(E::Refused("mission-report-clock-skew-invalid")); }
    let started = match swarm_wire_json::go_rfc3339::parse(&agent.started)
